static bool check(const Case& c,long budget=-1,bool scalar=false){
 Settings settings; Logger logger; Tokenizer tokenizer(settings,logger);
 std::istringstream in(c.code);
 if(!tokenizer.list.createTokens(in,"owned.cpp")||!tokenizer.simplifyTokens1(""))return false;
 faults=0;allocations=0;fault=budget;countAlloc=scalar;
 std::unique_ptr<CTU::FileInfo> info(CTU::getFileInfo(tokenizer));
 fault=-1;countAlloc=false;
 return info->toString()==c.expected && (budget<0||faults==1) && (!scalar||allocations==1);
}
int main(){
 unsigned checked=0,faultChecked=0,scalarChecked=0;
 for(const auto& c:cases){
  const bool scalar=std::string(c.name)=="scalar8"||std::string(c.name)=="scalar64";
  if(!check(c,-1,scalar))return 1;
  ++checked;if(scalar)++scalarChecked;
  if(std::string(c.name)=="positions")for(long budget=1;budget<=5;++budget){if(!check(c,budget))return 2;++faultChecked;}
 }
 if(checked!=18||faultChecked!=5||scalarChecked!=2)return 3;
 std::cout<<"ctu_native_cases="<<checked<<" allocation_fallback_cases="<<faultChecked<<" zero_optional_scalar_allocation_cases="<<scalarChecked<<"\n";
}
